// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2);
        uint initialC = address(c).balance;
        uint initialThis = address(this).balance;
        try c.deposit{value: amount1}() {} catch { return; }
        uint afterDepositC = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        uint afterWithdrawC = address(c).balance;
        try c.deposit{value: amount2}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;
        assertTrue(finalC == initialC && finalThis == initialThis && afterWithdrawC == initialC && afterDepositC == initialC + amount1);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2) public {
        _run(amount1, amount2);
    }

    receive() external payable {}
}
